storage.byId=id=>penpotUtils.findShapeById(id);storage.replace=(b,target,overlay=false)=>{for(const i of [...b.interactions])i.remove();(overlay?storage.overlay:storage.nav)(b,target);};storage.states={};storage.panel=(key,id,title,body,state,role='approver',width=600)=>{const n=Object.keys(storage.states).length,x=8000+(n%6)*700,y=10000+Math.floor(n/6)*900;const p=storage.screen(id,'B2 · '+key,x,y,width,760,role,state);storage.text(p,p.name+'/eyebrow','CommerceOps · Mock 原型 / 状态样例',x+24,y+24,width-48,12,'muted','400',24);storage.text(p,p.name+'/title',title,x+24,y+76,width-48,24,['conflict','read_failure','forbidden','permission_revoked'].includes(state)?'red':'ink','600',78);const box=storage.board(p,p.name+'/status',x+24,y+174,width-48,318,'canvas',10);storage.stroke(box);storage.text(box,p.name+'/body',body,x+44,y+196,width-88,14,'text','400',270);storage.text(p,p.name+'/boundary','仅验证设计交互 · 后端与飞书合同待验收',x+24,y+510,width-48,12,'muted','400',44);storage.states[key]=p;return p;};storage.link=(p,label,id,target,yy=570,key='secondary')=>{const b=storage.button(p,key,label,id,p.getSharedPluginData('commerceops-ux','stable-id'),'M1-E'+id.slice(-2),p.x+24,p.y+yy,p.width-48);if(target)storage.nav(b,target);return b;};
return {baseline:version.label,componentKeys:Object.keys(storage.components),tokens:Object.keys(storage.tokens),fileId:penpot.currentFile.id};

const f=penpot.currentFile,p=penpot.currentPage,all=penpotUtils.findShapes(()=>true,p.root),by=new Map(all.map(s=>[s.id,s]));if(f.id!=='7fd0f7d0-fdda-81c5-8008-c340d1377488')throw Error('wrong file');
const effectiveVisible=s=>{let c=s;while(c){if(c.hidden)return false;c=c.parent;}return true;};
const screens=p.root.children.filter(s=>/^M1-[SFM]\d\d /.test(s.name)).map(s=>({stableId:s.getSharedPluginData('commerceops-ux','stable-id'),shapeId:s.id,name:s.name,instance:s.getSharedPluginData('commerceops-ux','instance'),revision:s.getSharedPluginData('commerceops-ux','revision'),role:s.getSharedPluginData('commerceops-ux','role'),state:s.getSharedPluginData('commerceops-ux','state'),planId:s.getSharedPluginData('commerceops-ux','plan-id'),bounds:s.bounds}));
const controls=all.filter(s=>s.getSharedPluginData('commerceops-ux','event-id')).map(s=>({ownerBoardId:(()=>{let c=s;while(c.parent&&c.parent.id!==p.root.id)c=c.parent;return c.id;})(),shapeId:s.id,name:s.name,stableId:s.getSharedPluginData('commerceops-ux','stable-id'),eventId:s.getSharedPluginData('commerceops-ux','event-id'),screenId:s.getSharedPluginData('commerceops-ux','screen-id'),disabled:s.getSharedPluginData('commerceops-ux','ui-disabled')||s.getSharedPluginData('commerceops-ux','disabled-reason'),interactions:s.interactions.map(i=>({trigger:i.trigger,type:i.action.type,destination:i.action.destination?.id})),texts:penpotUtils.findShapes(t=>t.type==='text',s).map(t=>t.characters),bounds:s.bounds,visible:effectiveVisible(s)}));
const overflow=all.filter(s=>s.type==='text'&&effectiveVisible(s)).flatMap(s=>{const b=s.bounds,t=s.textBounds;return t&&(t.width>b.width+2||t.height>b.height+2)?[{id:s.id,bounds:b,textBounds:t}]:[];});
const outside=screens.flatMap(s=>penpotUtils.analyzeDescendants(by.get(s.shapeId),(root,c)=>effectiveVisible(c)&&!penpotUtils.isContainedIn(c,root)?c.id:null).map(x=>({screen:s.shapeId,shape:x.result})));
const narrow=['448723ff-8a21-80dc-8008-c373c1095dce','448723ff-8a21-80dc-8008-c373c88a718a','448723ff-8a21-80dc-8008-c373d4721f57','448723ff-8a21-80dc-8008-c373d743cc7c'].map(id=>{const b=by.get(id);return {shapeId:id,width:b.width,planId:b.getSharedPluginData('commerceops-ux','plan-id'),items:penpotUtils.findShapes(s=>s.getSharedPluginData('commerceops-ux','sku'),b).map(s=>({shapeId:s.id,sku:s.getSharedPluginData('commerceops-ux','sku'),quantity:Number(s.getSharedPluginData('commerceops-ux','quantity'))}))};});
return {fileId:f.id,pageId:p.id,revision:f.getSharedPluginData('commerceops-ux','revision'),revn:f.revn,versions:(await f.findVersions()).map(v=>({label:v.label,createdAt:v.createdAt})),screens,controls,narrow,rootOrder:p.root.children.map((s,j)=>({shapeId:s.id,name:s.name,index:p.root.children.length-1-j})),flows:p.flows.map(f=>({name:f.name,startingBoard:f.startingBoard.id})),counts:{shapes:all.length,texts:all.filter(s=>s.type==='text').length,flex:all.filter(s=>s.flex).length,tokenBound:all.filter(s=>Object.keys(s.tokens||{}).length).length,imageFills:all.filter(s=>s.fills?.some(f=>f.fillImage)).length},components:penpot.library.local.components.map(c=>({id:c.id,name:c.name})),tokenSets:penpot.library.local.tokens.sets.map(s=>({id:s.id,active:s.active,count:s.tokens.length})),overflow,outside,fontSizes:[...new Set(all.filter(s=>s.type==='text').map(s=>s.fontSize))],validation:f.validate()};

const f=penpot.currentFile;const all=penpotUtils.findShapes(()=>true,penpot.root);const newRoots=penpot.currentPage.root.children.filter(s=>s.name.includes('B3 ·'));storage.fixTextIds=[];for(const p of newRoots){for(const t of penpotUtils.findShapes(s=>s.type==='text',p)){if(p.name.includes('只读管理')){if(t.name.endsWith('/ role'))t.characters='admin · Mock';if(t.name.endsWith('/ user'))t.characters='陈管理';if(t.name.endsWith('/ breadcrumb'))t.characters='工作区  /  只读管理说明';if(t.name.endsWith('/ nav-future'))t.characters='仅内部工作项 · 无采购入库';}storage.fixTextIds.push(t.id);t.fontSize=String(Math.round(Number(t.fontSize))+.02);}}
